sys_script.script:
(function executeRule(current, previous) {

    // ---------------------------------
    // Validate source and destination
    // ---------------------------------

    var source =
        current.getValue('source_station');

    var destination =
        current.getValue('destination_station');


    if (!source || !destination) {

        gs.addErrorMessage(
            'Source and destination are required.'
        );

        current.setAbortAction(true);

        return;
    }


    if (source == destination) {

        gs.addErrorMessage(
            'Source and destination cannot be the same.'
        );

        current.setAbortAction(true);

        return;
    }


    // ---------------------------------
    // Validate passenger count
    // ---------------------------------

    var passengerCount =
        parseInt(
            current.getValue(
                'passenger_count'
            ),
            10
        );


    if (
        !passengerCount ||
        passengerCount < 1
    ) {

        gs.addErrorMessage(
            'Passenger count must be at least 1.'
        );

        current.setAbortAction(true);

        return;
    }


    if (passengerCount > 6) {

        gs.addErrorMessage(
            'Maximum 6 passengers are allowed.'
        );

        current.setAbortAction(true);

        return;
    }


    // ---------------------------------
    // Validate travel date
    // ---------------------------------

    var travelDate =
        current.getValue(
            'travel_date'
        );


    var today =
        new GlideDate().getValue();


    if (
        travelDate &&
        travelDate < today
    ) {

        gs.addErrorMessage(
            'Travel date cannot be in the past.'
        );

        current.setAbortAction(true);

        return;
    }


    // ---------------------------------
    // Recalculate fare on server
    // ---------------------------------

    var service =
        new MetroFareService();


    var result =
        service.calculateFare(
            source,
            destination,
            current.getValue(
                'journey_type'
            ),
            passengerCount
        );


    if (!result.success) {

        gs.addErrorMessage(
            result.message
        );

        current.setAbortAction(true);

        return;
    }


    // ---------------------------------
    // Store trusted calculated values
    // ---------------------------------

    current.setValue(
        'distance_km',
        result.distance
    );


    current.setValue(
        'duration_minutes',
        result.duration
    );


    current.setValue(
        'base_fare',
        result.baseFare
    );


    current.setValue(
        'total_fare',
        result.totalFare
    );


})(current, previous);
